final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Amazon Verified Permissions policy store implementing Cedar-based access
  control for a bookstore application. The stack defines an inline Bookstore
  schema (Role, User and Book entities plus the View and ViewWithPremiumOffers
  actions) that is enforced in STRICT validation mode, a set of static Cedar
  policies, and an SSM Parameter that publishes the generated policy store ID
  for downstream consumers.

Resources:

  ###############################################################################
  # Policy store: hosts the Cedar schema and the static authorization policies
  ###############################################################################
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "memberOfTypes": []
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  ###############################################################################
  # Policy 1 - Admins may view any book
  ###############################################################################
  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book.
          Statement: |
            permit (
                principal in Bookstore::Role::"Admin",
                action == Bookstore::Action::"View",
                resource
            );

  ###############################################################################
  # Policy 2 - Explicitly deny one named administrator, overriding the admin permit
  ###############################################################################
  ForbidNamedAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the specific administrator user adminForbidden from viewing any book, overriding the general Admin permission.
          Statement: |
            forbid (
                principal == Bookstore::User::"adminForbidden",
                action == Bookstore::Action::"View",
                resource
            );

  ###############################################################################
  # Policy 3 - Publishers may view only the books they own
  ###############################################################################
  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they themselves own.
          Statement: |
            permit (
                principal in Bookstore::Role::"Publisher",
                action == Bookstore::Action::"View",
                resource
            )
            when {
                resource.owner == principal
            };

  ###############################################################################
  # Policy 4 - One named user may view one named book
  ###############################################################################
  AliceViewBookOnePolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit the specific user alice to view the specific book book1.
          Statement: |
            permit (
                principal == Bookstore::User::"alice",
                action == Bookstore::Action::"View",
                resource == Bookstore::Book::"book1"
            );

  ###############################################################################
  # Policy 5 - Customers with two or more years of membership may view premium offers
  ###############################################################################
  CustomerViewPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Customer role to view premium offers once they have been a member for two years or more.
          Statement: |
            permit (
                principal in Bookstore::Role::"Customer",
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource
            )
            when {
                principal has yearsAsMember && principal.yearsAsMember >= 2
            };

  ###############################################################################
  # Policy 6 - Customers with less than two years of membership may not view premium offers
  ###############################################################################
  CustomerBelowMinimumMembershipPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid users in the Customer role with less than two years of membership from viewing premium offers.
          Statement: |
            forbid (
                principal in Bookstore::Role::"Customer",
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource
            )
            when {
                principal has yearsAsMember && principal.yearsAsMember < 2
            };

  ###############################################################################
  # Policy 7 - Both actions are denied when the request region is not the US
  ###############################################################################
  ForbidNonUnitedStatesRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the View and ViewWithPremiumOffers actions for every principal whenever the request context region is not the United States.
          Statement: |
            forbid (
                principal,
                action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
                resource
            )
            when {
                context.region != "United States"
            };

  ###############################################################################
  # Publish the generated policy store ID for other stack components
  ###############################################################################
  BookstorePolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId
      Description: Identifier of the Amazon Verified Permissions policy store that hosts the bookstore authorization policies and Cedar schema.
